    const wrapper = document.createElement('div');
    wrapper.className = 'example';

    const h3 = document.createElement('h3');
    h3.style.margin = '0';

    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'faq-question';
    button.setAttribute('aria-expanded', 'false');

    const questionSpan = document.createElement('span');
    questionSpan.textContent = question;

    const icon = document.createElement('span');
    icon.className = 'icon';
    icon.innerHTML = '&#9662;'; // Down arrow
    icon.setAttribute('aria-hidden', 'true');

    button.appendChild(questionSpan);
    button.appendChild(icon);
    h3.appendChild(button);

    const details = document.createElement('div');
    details.className = 'details';
    details.textContent = answer;
    details.hidden = true;

    button.addEventListener('click', () => {
        const isExpanded = button.getAttribute('aria-expanded') === 'true';
        button.setAttribute('aria-expanded', !isExpanded);
        details.hidden = isExpanded;
    });

    wrapper.appendChild(h3);
    wrapper.appendChild(details);

    return wrapper;
}

function App() {
    const container = document.createElement('div');

    const h1 = document.createElement('h1');
    h1.textContent = 'Cat FAQ';
    container.appendChild(h1);

    const faqList = document.createElement('div');
    faqList.className = 'faq-container';

    faqData.forEach(item => {
        faqList.appendChild(FAQItem(item));
    });

    container.appendChild(faqList);
    return container;
}

document.addEventListener('DOMContentLoaded', () => {
    const root = document.getElementById('root');
    root.appendChild(App());
});

