/**
 * Simple React-like component system for a standalone FAQ page
 */

const faqData = [
    {
        question: "Why do cats purr?",
        answer: "Cats purr for many reasons, including contentment, self-soothing when stressed or in pain, and even to promote healing. The frequency of a cat's purr has been shown to improve bone density and speed up the healing of tendons."
    },
    {
        question: "Why do cats have whiskers?",
        answer: "Whiskers are highly sensitive tactile organs. They help cats navigate in the dark, detect changes in air currents (which helps them hunt), and determine if they can fit through narrow openings."
    },
    {
        question: "Why do cats like catnip?",
        answer: "Catnip contains nepetalactone, a chemical that binds to receptors in a cat's nose. This triggers a response in the brain that results in a temporary state of euphoria for about 70-80% of cats."
    },
    {
        question: "How long do cats sleep?",
        answer: "Cats are crepuscular, meaning they are most active at dawn and dusk. To conserve energy for hunting, they sleep an average of 12 to 16 hours a day, with some sleeping up to 20 hours!"
    },
    {
        question: "Why do cats knead?",
        answer: "Kneading (or 'making biscuits') is a behavior cats carry over from kittenhood, when they would knead their mother to stimulate milk flow. In adults, it's often a sign of comfort, security, and affection."
    }
];

function FAQItem({ question, answer }) {
    const wrapper = document.createElement('div');
    wrapper.className = 'example';

    const h3 = document.createElement('h3');
    h3.style.margin = '0';

    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'faq-question';
    button.setAttribute('aria-expanded', 'false');

    const questionSpan = document.createElement('span');
    questionSpan.textContent = question;

    const icon = document.createElement('span');
    icon.className = 'icon';
    icon.innerHTML = '&#9662;'; // Down arrow
    icon.setAttribute('aria-hidden', 'true');

    button.appendChild(questionSpan);
    button.appendChild(icon);
    h3.appendChild(button);

    const details = document.createElement('div');
    details.className = 'details';
    details.textContent = answer;
    details.hidden = true;

    button.addEventListener('click', () => {
        const isExpanded = button.getAttribute('aria-expanded') === 'true';
        button.setAttribute('aria-expanded', !isExpanded);
        details.hidden = isExpanded;
    });

    wrapper.appendChild(h3);
    wrapper.appendChild(details);

    return wrapper;
}

function App() {
    const container = document.createElement('div');

    const h1 = document.createElement('h1');
    h1.textContent = 'Cat FAQ';
    container.appendChild(h1);

    const faqList = document.createElement('div');
    faqList.className = 'faq-container';

    faqData.forEach(item => {
        faqList.appendChild(FAQItem(item));
    });

    container.appendChild(faqList);
    return container;
}

document.addEventListener('DOMContentLoaded', () => {
    const root = document.getElementById('root');
    root.appendChild(App());
});
    </script>
</body>
</html>
